css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f2f5f8;color:#233b4c;font:15px/1.85 "Microsoft YaHei",system-ui,sans-serif}a{color:#087e86}header{padding:15px 30px;background:#fff;border-bottom:1px solid #dce5ed;display:flex;justify-content:space-between;gap:20px}header b{color:#087e86}header span{font-size:13px;color:#667d8e}.layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:26px;max-width:1510px;margin:26px auto;padding:0 24px}aside{position:sticky;top:20px;align-self:start}aside a{display:block;padding:8px;text-decoration:none;font-size:13px}main{min-width:0}article,.sketch{background:white;border:1px solid #dce5ed;border-radius:16px;padding:30px;margin-bottom:24px}h1{font-size:32px;line-height:1.45}h2{font-size:24px;padding-top:18px;border-top:1px solid #e4ebf0;margin-top:38px;scroll-margin-top:20px}h3{font-size:18px}p{margin:15px 0}.tablewrap{overflow:auto;margin:22px 0;border:1px solid #dce5ed;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.75}th,td{padding:11px 14px;border:1px solid #e3eaf0;min-width:110px;vertical-align:top}th{background:#edf4f7;text-align:left}tr:nth-child(even){background:#fafcfd}code{background:#edf3f6;padding:2px 4px;font:12px Consolas,monospace;overflow-wrap:anywhere}strong{color:#124f61}.eyebrow{font-size:11px;letter-spacing:2px;color:#087e86;font-weight:bold}.sketch h2{border:0;margin:5px 0;padding:0}.sketchhead{display:flex;align-items:center;justify-content:space-between;gap:15px}.sketchhead p{margin:0;font-size:12px;color:#6b7f8f}.switches{display:flex;gap:6px;flex-wrap:wrap}button{font:inherit}.switches button{border:1px solid #d4e1e7;padding:7px 13px;border-radius:8px;background:#fff;cursor:pointer}.switches button.selected{background:#087e86;color:white;border-color:#087e86}.shoplabel{font-size:12px;margin:22px 0 8px;color:#687e8e}.offer{background:#eaf5ff;border:4px solid #95c8e9;border-radius:25px;overflow:hidden;aspect-ratio:1080/550;display:flex;flex-direction:column}.offer-rewards{flex:1;display:grid;grid-template-columns:34% 25% 41%;align-items:center;padding:14px 16px;min-height:0}.target{display:flex;align-items:center;justify-content:center;flex-direction:column;position:relative;height:100%}.pill{font-size:clamp(10px,1.1vw,16px);background:#fff9db;padding:2px 15px;border-radius:20px;color:#8b691f}.target img{width:48%;height:56%;object-fit:contain}.target strong{font-size:clamp(24px,3vw,48px);line-height:1.2}.target small{font-size:12px;color:#71899c}.currency{display:flex;flex-direction:column;align-items:center;justify-content:center;background:#ffffff90;border-radius:15px;height:85%;gap:5px}.currency strong{font-size:clamp(15px,2vw,27px)}.currency span{color:#647d91;font-size:13px}.currency .diamond{color:#7599d4;font-size:clamp(30px,5vw,70px);line-height:1.2}.extras{display:flex;justify-content:space-around;align-items:center;padding:0 10px;gap:5px}.extra{display:flex;flex-direction:column;align-items:center;gap:4px;min-width:0;flex:1}.extra img{width:100%;max-height:90px;object-fit:contain}.extra strong{font-size:clamp(14px,1.8vw,26px)}.extra small{font-size:12px;white-space:nowrap}.offer-bottom{display:flex;align-items:center;justify-content:space-between;background:#d4eaff;padding:14px 28px;min-height:25%}.offer-bottom div{display:flex;flex-direction:column}.offer-bottom b{font-size:clamp(18px,2.5vw,36px)}.offer-bottom small{font-size:12px;color:#617e94}.pay{background:#58a83b;color:#fff;border:2px solid #438f2c;border-radius:14px;min-width:31%;padding:10px;font-size:clamp(18px,2.5vw,36px);font-weight:bold;opacity:1}.dots{display:flex;justify-content:center;gap:8px;padding:11px}.dots i{background:#d7e0e8;width:8px;height:8px;border-radius:50%}.dots i:first-child{background:#087e86}.sketchcaption{font-size:12px;color:#6b8191;margin:5px 0}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:24px}.flow div{padding:13px;border-radius:10px;background:#f1f7f7}.flow b,.flow span{display:block}.flow b{color:#087e86}.flow span{font-size:12px}.notice{border-left:4px solid #d3aa4d;background:#fff8e6;padding:15px;margin-bottom:20px;font-size:13px}li{margin:10px 0}footer{color:#708595;font-size:12px;padding:5px 10px 30px}@media(max-width:1000px){.layout{display:block;padding:0 14px}aside{position:static;display:none}.sketchhead{flex-direction:column;align-items:flex-start}.offer{min-height:290px}.offer-rewards{padding:9px 7px}.offer-bottom{padding:10px 16px}.target img{height:50%}.flow{grid-template-columns:1fr}article,.sketch{padding:20px}.extras{gap:2px;padding:0 5px}}@media print{aside,header,.switches{display:none}.layout{display:block;padding:0}body{background:white}article,.sketch{border:0;padding:10px}.tablewrap{overflow:visible}h2{break-after:avoid}.offer{max-width:950px}}'''
js='''const icons=ICONS; const names={'11':'撤回','12':'风车','13':'磁铁','14':'手套'}; const total={'11':8,'12':5,'13':4,'14':5};function choose(id){document.getElementById('target-icon').src=icons[id];document.getElementById('target-icon').alt=names[id]+'图标';document.getElementById('target-count').textContent='×'+total[id];document.getElementById('offer-title').textContent=names[id]+'补给';document.getElementById('extras').replaceChildren();for(const other of ['11','14','13','12']){if(other===id)continue;const d=document.createElement('div');d.className='extra';const img=document.createElement('img');img.src=icons[other];img.alt=names[other];const n=document.createElement('strong');n.textContent='×'+(id==='11'?2:1);const name=document.createElement('small');name.textContent=names[other];d.append(img,n,name);document.getElementById('extras').append(d)}document.querySelectorAll('[data-id]').forEach(b=>{b.classList.toggle('selected',b.dataset.id===id);b.setAttribute('aria-pressed',b.dataset.id===id)})}document.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.id)));choose('14');'''.replace('ICONS',json.dumps(icons))
